740 | // DeleteSpaceMember removes a membership or lets a member leave a space.
741 | func (s *APIV1Service) DeleteSpaceMember(ctx context.Context, request *v1pb.DeleteSpaceMemberRequest) (*emptypb.Empty, error) {
742 | 	currentUser, err := s.requireCurrentSpaceUser(ctx)
743 | 	if err != nil {
744 | 		return nil, err
745 | 	}
746 | 	_, targetUser, callerMembership, targetMembership, err := s.resolveSpaceMemberResource(ctx, request.Name, currentUser)
747 | 	if err != nil {
748 | 		return nil, err
749 | 	}
750 | 	isSelf := targetUser.ID == currentUser.ID
751 | 	if !isSelf {
752 | 		if err := requireSpaceAdministrator(callerMembership); err != nil {
753 | 			return nil, err
754 | 		}
755 | 	}
756 | 	if err := s.Store.DeleteSpaceMember(ctx, &store.DeleteSpaceMember{
757 | 		SpaceID: targetMembership.SpaceID,
758 | 		UserID:  targetMembership.UserID,
759 | 	}, currentUser.ID); err != nil {
760 | 		return nil, mapSpaceMutationError(err, "failed to delete space member")
761 | 	}
762 | 	s.SSEHub.publishSpaceChanged()
763 | 	return &emptypb.Empty{}, nil
764 | }
","bytes":6641},{"id":"ev-4613bf5cc02521f91db5","repository":"usememos/memos","sourceRef":"cb42e326ba9cc266a6a9570c53e0fe04c62793f4","path":"store/db/postgres/space.go","sha256":"904d4817ea006a369061588aa2ce843a6d9bd76ca0705b393f2dcad6d6896eb4","startLine":437,"endLine":487,"text":"437 | func (d *DB) DeleteSpaceMember(ctx context.Context, delete *store.DeleteSpaceMember, actorUserID int32) error {
438 | 	tx, err := d.db.BeginTx(ctx, nil)
439 | 	if err != nil {
440 | 		return err
441 | 	}
442 | 	defer func() { _ = tx.Rollback() }()
443 | 	userStatuses, err := readPostgresUserStatuses(ctx, tx, actorUserID, delete.UserID)
444 | 	if err != nil {
445 | 		return err
446 | 	}
447 | 	if actorUserID != delete.UserID && userStatuses[actorUserID] != store.Normal {
448 | 		return store.ErrSpacePermissionDenied
449 | 	}
450 | 	var spaceID int32
451 | 	if err := tx.QueryRowContext(ctx, "SELECT id FROM space WHERE id = $1", delete.SpaceID).Scan(&spaceID); err != nil {
452 | 		if errors.Is(err, sql.ErrNoRows) {
453 | 			return store.ErrSpaceNotFound
454 | 		}
455 | 		return err
456 | 	}
457 | 	if actorUserID != delete.UserID {
458 | 		var role store.SpaceMemberRole
459 | 		if err := tx.QueryRowContext(ctx, "SELECT role FROM space_member WHERE space_id = $1 AND user_id = $2 AND status = $3", delete.SpaceID, actorUserID, store.SpaceMemberStatusActive).Scan(&role); errors.Is(err, sql.ErrNoRows) {
460 | 			return store.ErrSpacePermissionDenied
461 | 		} else if err != nil {
462 | 			return err
463 | 		} else if role != store.SpaceMemberRoleAdmin {
464 | 			return store.ErrSpacePermissionDenied
465 | 		}
466 | 	}
467 | 	member, err := getPostgresSpaceMember(ctx, tx, delete.SpaceID, delete.UserID)
468 | 	if err != nil {
469 | 		if errors.Is(err, sql.ErrNoRows) {
470 | 			return store.ErrSpaceMemberNotFound
471 | 		}
472 | 		return err
473 | 	}
474 | 	if member.Role == store.SpaceMemberRoleAdmin && userStatuses[delete.UserID] == store.Normal {
475 | 		var count int
476 | 		if err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM space_member sm JOIN "user" u ON u.id = sm.user_id WHERE sm.space_id = $1 AND sm.status = $2 AND sm.role = $3 AND u.row_status = 'NORMAL'`, delete.SpaceID, store.SpaceMemberStatusActive, store.SpaceMemberRoleAdmin).Scan(&count); err != nil {
477 | 			return err
478 | 		}
479 | 		if count <= 1 {
480 | 			return store.ErrLastSpaceAdmin
481 | 		}
482 | 	}
483 | 	if _, err := tx.ExecContext(ctx, "DELETE FROM space_member WHERE space_id = $1 AND user_id = $2 AND status = $3", delete.SpaceID, delete.UserID, store.SpaceMemberStatusActive); err != nil {
484 | 		return err
485 | 	}
